#if canImport(FoundationEssentials)
import FoundationEssentials
#else
import Foundation
#endif

/// Emits one ``Theme`` as CSS custom properties, scoped to `[data-theme-name="<id>"]` so several themes can
/// coexist on a page.
///
/// Nothing in the output is typed here: every colour, weight, size and font comes from the theme, and the
/// header carries the theme's content hash. A test checks that every colour literal in a generated file is a
/// value of its theme.
///
/// ### Blocks, in cascade order
/// 1. the light values, with the structure (rules, layout, marks, type);
/// 2. `prefers-contrast: more`, light;
/// 3. `prefers-color-scheme: dark`, unless the element is pinned light (`data-theme="light"` or
///    `data-bs-theme="light"`);
/// 4. the explicit dark selectors, which match the themed element or any element inside a dark one;
/// 5. `prefers-contrast: more` with the dark scheme;
/// 6. `prefers-contrast: more` with the explicit dark selectors.
///
/// Blocks 3 to 6 exist only for a theme that declares ``AppearanceSupport/both``; a block with nothing in it
/// is left out. A light-only theme says `color-scheme: light`, a fixed-dark one `color-scheme: dark`.
///
/// Increased-contrast blocks carry only the colours that have a measured increased-contrast value: the
/// others carry through, as ``Adaptive/value(in:increasedContrast:)`` does.
///
/// The card chrome is emitted as `--card-chrome` and the `--card-surface`, `--card-top-rule`, `--card-top-color`, `--card-min` and `--card-gap` properties derived from it.
///
/// Not emitted as CSS: value-label and series-labelling flags, axis placement and number formats (the value halo, card
/// border and padding, reference-label gap, mark default fill and emphasis are emitted). They are not
/// presentational properties a stylesheet can use; the theme's JSON carries them.
public enum ThemeCSSEmitter {
    /// The complete stylesheet for a theme, ending in a newline.
    ///
    /// - Throws: An encoding error if the theme cannot be encoded for its content hash (a NaN weight, for instance).
    public static func emit(_ theme: Theme) throws -> String {
        try ThemeIdentity.requireValidID(of: theme)
        let scope = "[data-theme-name=\"\(theme.id)\"]"
        let notPinnedLight = ":not([data-theme=\"light\"]):not([data-bs-theme=\"light\"])"
        let hash = try ThemeCodec.fingerprint(of: theme)
        var lines = ["/* Generated by design-tokens. Do not edit. Theme: \(theme.id) (\(ThemeIdentity.cssCommentText(theme.name))) | DesignTokens \(DesignTokens.version) | System colours: snapshot of \(Snapshot.systemRelease) | hash fnv1a64:\(hash) */"]

        let baseScheme = theme.appearances == .fixedDark ? "dark" : "light"
        lines.append("\(scope) {")
        lines.append("  color-scheme: \(baseScheme);")
        lines.append(contentsOf: colourDeclarations(theme, appearance: .light, increased: false, only: .all))
        lines.append(contentsOf: structureDeclarations(theme))
        lines.append("}")

        let increasedLight = colourDeclarations(theme, appearance: .light, increased: true, only: .increasedOnly)
        if !increasedLight.isEmpty {
            lines.append("@media (prefers-contrast: more) {")
            lines.append("  \(scope) {")
            lines.append(contentsOf: increasedLight.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
        }

        lines.append(contentsOf: surfaceRules(theme, scope: scope))

        guard theme.appearances == .both else { return lines.joined(separator: "\n") + "\n" }

        let dark = ["  color-scheme: dark;"] + colourDeclarations(theme, appearance: .dark, increased: false, only: .darkOnly)
        let explicit = ["\(scope)[data-theme=\"dark\"]", "\(scope)[data-bs-theme=\"dark\"]",
                        "[data-theme=\"dark\"] \(scope)", "[data-bs-theme=\"dark\"] \(scope)"]
        lines.append("@media (prefers-color-scheme: dark) {")
        lines.append("  \(scope)\(notPinnedLight) {")
        lines.append(contentsOf: dark.map { "  " + $0 })
        lines.append("  }")
        lines.append("}")
        lines.append(explicit.joined(separator: ",\n") + " {")
        lines.append(contentsOf: dark)
        lines.append("}")

        let increasedDark = colourDeclarations(theme, appearance: .dark, increased: true, only: .increasedOnly)
        if !increasedDark.isEmpty {
            lines.append("@media (prefers-contrast: more) and (prefers-color-scheme: dark) {")
            lines.append("  \(scope)\(notPinnedLight) {")
            lines.append(contentsOf: increasedDark.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
            lines.append("@media (prefers-contrast: more) {")
            lines.append("  " + explicit.joined(separator: ",\n  ") + " {")
            lines.append(contentsOf: increasedDark.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
        }
        return lines.joined(separator: "\n") + "\n"
    }

    // MARK: Surfaces

    /// The component classes a surface role styles; a role with none (scroll bars, selection) has no web counterpart yet.
    private static func selectors(for role: SurfaceRole) -> [String] {
        switch role {
        case .desktop: [""]
        case .window: [".dt-page"]
        case .panel: [".dt-card"]
        case .button: [".dt-button"]
        case .buttonDefault: [".dt-button--primary"]
        case .field: [".dt-input", ".dt-select", ".dt-textarea"]
        case .titleBar: [".dt-titlebar"]
        case .titleStripes: [".dt-titlebar__stripes"]
        case .windowBox: [".dt-titlebar__box"]
        case .windowBoxZoom: [".dt-titlebar__box--zoom"]
        case .windowBoxMinimize: [".dt-titlebar__box--minimize"]
        case .selection: []
        // drawn by menuRules, which lays a menu bar and a menu out
        case .menu, .menuBar, .menuTitle, .menuItem, .menuBarItem, .menuSeparator, .menuArrow: []
        // drawn by dockRules
        case .dockTile, .dockLabel: []
        // drawn by scrollBarRules, which lays a scroll bar out and turns a vertical one about its diagonal
        case .scrollBar, .scrollTrack, .scrollThumb, .scrollGrip, .scrollArrowStart, .scrollArrowEnd: []
        }
    }

    /// The pseudo-class suffix that selects a state, or `nil` for one the web components do not distinguish.
    private static func suffix(for state: ComponentState) -> String? {
        switch state {
        case .rest: ""
        case .hover: ":not(:disabled):hover"
        case .active: ":not(:disabled):active"
        case .focus: ":focus-visible"
        case .disabled: ":disabled"
        case .invalid: "[aria-invalid=\"true\"]"
        case .activeHover, .focusHover, .loading, .open, .closed: nil
        }
    }

    /// The selector tails of a state: a disabled control is `:disabled` or `aria-disabled="true"`, as the components stylesheet counts it.
    private static func tails(for state: ComponentState) -> [String] {
        guard state == .disabled else { return suffix(for: state).map { [$0] } ?? [] }
        return ["[aria-disabled=\"true\"]", ":disabled"]
    }

    /// Rules for the theme's surface recipes, scoped like the custom properties. A recipe owns its control's edges, so the component's own
    /// border is removed. A theme with no surfaces emits nothing.
    private static func surfaceRules(_ theme: Theme, scope: String) -> [String] {
        guard let surfaces = theme.surfaces else { return [] }
        func literal(_ reference: ColourReference) -> String {
            let adaptive = ColorRole(rawValue: reference.source).map { theme.palette[$0] } ?? theme.palette.extras[reference.source]
            guard let value = adaptive?.light else { return "transparent" }
            return ColorValue(value.rgb, alpha: value.alpha * reference.opacity).hex
        }
        var lines: [String] = []
        for role in SurfaceRole.allCases {
            let classes = selectors(for: role)
            guard !classes.isEmpty, let states = surfaces.recipes[role] else { continue }
            // The components stylesheet outlines a hovered or pressed button; no classic platform did, and the recipes draw the states, so a skin
            // takes the outline off (the selectors match its own, plus the class, so they win by specificity wherever the files are linked).
            if role == .button || role == .buttonDefault {
                let live = ":not([disabled]):not([aria-disabled=\"true\"])"
                let hover = classes.map { "\(scope) \($0)\(live):hover" }
                let active = classes.map { "\(scope) \($0)\(live):active" }
                lines.append((hover + active).joined(separator: ",\n") + " {")
                lines.append("  outline: 0;")
                lines.append("}")
            }
            for state in ComponentState.allCases {
                let stateTails = tails(for: state)
                guard let recipe = states[state], !stateTails.isEmpty else { continue }
                // an inactive window is its title bar marked disabled, so the bar's parts follow the bar rather than carrying the mark themselves
                let barParts: Set<SurfaceRole> = [.titleStripes, .windowBox, .windowBoxZoom, .windowBoxMinimize]
                let selector = state == .disabled && barParts.contains(role)
                    ? classes.map { "\(scope) .dt-titlebar[aria-disabled=\"true\"] \($0)" }.joined(separator: ",\n")
                    : classes.flatMap { cls in stateTails.map { "\(scope)\(cls.isEmpty ? "" : " " + cls)\($0)" } }.joined(separator: ",\n")
                lines.append(selector + " {")
                lines.append("  border: 0;")
                // the recipe draws a disabled control whole, and a focus ring replaces the components stylesheet's outline
                if state == .disabled { lines.append("  opacity: 1;") }
                if state == .focus { lines.append("  outline: 0;") }
                if role == .buttonDefault, state == .rest, surfaces.defaultRingExtra > 0 {
                    // the ring is outside the measured button, so the box grows by it on each side
                    let extra = SurfaceCSS.px(surfaces.defaultRingExtra)
                    lines.append("  min-block-size: calc(var(--control-height, calc(var(--space-unit) * 11)) + \(SurfaceCSS.px(surfaces.defaultRingExtra * 2)));")
                    lines.append("  padding: var(--control-pad-y, calc(var(--space-unit) * 1)) calc(var(--space-unit) * 4 + \(extra));")
                }
                lines.append(contentsOf: SurfaceCSS.declarations(for: recipe, resolve: reference, literal: literal).map { "  \($0);" })
                lines.append("}")
            }
        }
        lines.append(contentsOf: titleBarRules(theme, scope: scope))
        lines.append(contentsOf: scrollBarRules(theme, scope: scope))
        lines.append(contentsOf: menuRules(theme, scope: scope))
        lines.append(contentsOf: dockRules(theme, scope: scope))
        return lines
    }

    /// Menus: `dt-menubar` (a row of `dt-menubar__item` titles) and `dt-menu` (a column of an optional `dt-menu__title` and
    /// `dt-menu__item` rows). The highlighted title or row carries `aria-selected="true"`, and its drawing is the recipe's `hover` state, so a
    /// pointer over an item and a keyboard choice look the same. The theme's ``MenuMetrics`` sizes each part; a part the theme has no recipe
    /// for is not emitted.
    private static func menuRules(_ theme: Theme, scope: String) -> [String] {
        guard let metrics = theme.menus, let surfaces = theme.surfaces else { return [] }
        func px(_ value: Double) -> String { SurfaceCSS.px(value) }
        func literal(_ reference: ColourReference) -> String {
            let adaptive = ColorRole(rawValue: reference.source).map { theme.palette[$0] } ?? theme.palette.extras[reference.source]
            guard let value = adaptive?.light else { return "transparent" }
            return ColorValue(value.rgb, alpha: value.alpha * reference.opacity).hex
        }
        let inset = metrics.barInset
        var rowPadding = "0 \(px(metrics.itemPadding))"
        if let own = metrics.itemInset { rowPadding = "\(px(own.top)) \(px(own.trailing)) \(px(own.bottom)) \(px(own.leading))" }
        let row = ["display: flex", "align-items: center", "box-sizing: border-box", "padding: \(rowPadding)"]
        // role, selector, layout declarations
        var parts: [(SurfaceRole, String, [String])] = []
        if let height = metrics.barHeight {
            parts.append((.menuBar, ".dt-menubar", ["display: flex", "align-items: stretch", "box-sizing: border-box", "block-size: \(px(height))",
                "padding: \(px(inset.top)) \(px(inset.trailing)) \(px(inset.bottom)) \(px(inset.leading))"]))
            // a bar's title has its own drawing where a theme gives one, and is a row of the menu otherwise
            parts.append((surfaces.recipes[.menuBarItem] != nil ? .menuBarItem : .menuItem, ".dt-menubar__item", row))
        }
        var column = ["display: flex", "flex-direction: column", "box-sizing: border-box"]
        if let width = metrics.menuWidth { column.append("inline-size: \(px(width))") }
        if let pad = metrics.menuInset { column.append("padding: \(px(pad.top)) \(px(pad.trailing)) \(px(pad.bottom)) \(px(pad.leading))") }
        parts.append((.menu, ".dt-menu", column))
        if let height = metrics.titleHeight { parts.append((.menuTitle, ".dt-menu__title", row + ["block-size: \(px(height))"])) }
        parts.append((.menuItem, ".dt-menu__item", row + ["block-size: \(px(metrics.itemHeight))"]))
        if let height = metrics.separatorHeight {
            parts.append((.menuSeparator, ".dt-menu__separator", ["flex: none", "box-sizing: border-box", "block-size: \(px(height))"]))
        }
        if case .pattern(let tile)? = surfaces.recipes[.menuArrow]?[.rest]?.layers.last {
            parts.append((.menuArrow, ".dt-menu__arrow", ["flex: none", "align-self: flex-start", "inline-size: \(tile.width)px", "block-size: \(tile.height)px",
                "margin-inline-start: auto", "margin-block-start: \(px(metrics.arrowInset))"]))
        }
        var lines: [String] = []
        for (role, selector, layout) in parts {
            guard let states = surfaces.recipes[role] else { continue }
            lines.append("\(scope) \(selector) {")
            lines.append(contentsOf: (layout + ["border: 0"]).map { "  \($0);" })
            if let rest = states[.rest] {
                lines.append(contentsOf: SurfaceCSS.declarations(for: rest, resolve: reference, literal: literal).map { "  \($0);" })
            }
            lines.append("}")
            // the lit row's arrow is the child of the lit row, so it is selected through the row
            let lit = role == .menuArrow ? "\(scope) .dt-menu__item[aria-selected=\"true\"] \(selector)" : "\(scope) \(selector)[aria-selected=\"true\"]"
            if let recipe = states[.hover] {
                lines.append(lit + " {")
                lines.append(contentsOf: SurfaceCSS.declarations(for: recipe, resolve: reference, literal: literal).map { "  \($0);" })
                lines.append("}")
            }
            if let recipe = states[.disabled] {
                lines.append("\(scope) \(selector)[aria-disabled=\"true\"] {")
                lines.append(contentsOf: SurfaceCSS.declarations(for: recipe, resolve: reference, literal: literal).map { "  \($0);" })
                lines.append("}")
            }
        }
        return lines
    }

    /// A dock: `dt-dock__tile`, a square of the theme's ``DockMetrics/tileSize`` drawn by the ``SurfaceRole/dockTile`` recipe. The icon goes in
    /// the tile; the theme draws the frame and the ground.
    private static func dockRules(_ theme: Theme, scope: String) -> [String] {
        guard let metrics = theme.dock, let recipe = theme.surfaces?.recipes[.dockTile]?[.rest] else { return [] }
        func literal(_ reference: ColourReference) -> String {
            let adaptive = ColorRole(rawValue: reference.source).map { theme.palette[$0] } ?? theme.palette.extras[reference.source]
            guard let value = adaptive?.light else { return "transparent" }
            return ColorValue(value.rgb, alpha: value.alpha * reference.opacity).hex
        }
        let side = SurfaceCSS.px(metrics.tileSize)
        var lines = ["\(scope) .dt-dock__tile {", "  position: relative;", "  box-sizing: border-box;", "  flex: none;", "  inline-size: \(side);", "  block-size: \(side);", "  padding: 0;", "  border: 0;"]
        lines.append(contentsOf: SurfaceCSS.declarations(for: recipe, resolve: reference, literal: literal).map { "  \($0);" })
        lines.append("}")
        if let height = metrics.labelHeight, let label = theme.surfaces?.recipes[.dockLabel]?[.rest] {
            lines += ["\(scope) .dt-dock__label {", "  position: absolute;", "  inset-block-start: \(SurfaceCSS.px(metrics.labelInset));", "  inset-inline: 0;",
                      "  box-sizing: border-box;", "  block-size: \(SurfaceCSS.px(height));", "  overflow: hidden;", "  white-space: nowrap;", "  text-align: center;",
                      "  font-size: 9px;", "  line-height: \(SurfaceCSS.px(height));"]
            lines.append(contentsOf: SurfaceCSS.declarations(for: label, resolve: reference, literal: literal).map { "  \($0);" })
            lines.append("}")
        }
        return lines
    }

    /// A scroll bar: `dt-scrollbar` (with `data-orientation="horizontal"` or `"vertical"`) holding a `dt-scrollbar__arrow--start`, a
    /// `dt-scrollbar__track` with a `dt-scrollbar__thumb` (and its `dt-scrollbar__grip`) in it, and a `dt-scrollbar__arrow--end`, in that
    /// markup order. The theme's ``ScrollBarMetrics`` sets where the arrows sit; the recipes are authored for a horizontal bar and a vertical
    /// one is drawn from their transposes, so the markup does not change from one theme to another. The author sizes the thumb and puts it
    /// along the track (`inline-size` and `margin-inline-start` when horizontal, `block-size` and `margin-block-start` when vertical).
    private static func scrollBarRules(_ theme: Theme, scope: String) -> [String] {
        guard let metrics = theme.scrollBar, let surfaces = theme.surfaces else { return [] }
        func px(_ value: Double) -> String { SurfaceCSS.px(value) }
        func literal(_ reference: ColourReference) -> String {
            let adaptive = ColorRole(rawValue: reference.source).map { theme.palette[$0] } ?? theme.palette.extras[reference.source]
            guard let value = adaptive?.light else { return "transparent" }
            return ColorValue(value.rgb, alpha: value.alpha * reference.opacity).hex
        }
        let parts: [(SurfaceRole, String)] = [
            (.scrollBar, ".dt-scrollbar"), (.scrollTrack, ".dt-scrollbar__track"), (.scrollThumb, ".dt-scrollbar__thumb"),
            (.scrollGrip, ".dt-scrollbar__grip"), (.scrollArrowStart, ".dt-scrollbar__arrow--start"), (.scrollArrowEnd, ".dt-scrollbar__arrow--end"),
        ]
        let vertical = "[data-orientation=\"vertical\"]"
        let thickness = px(metrics.thickness)
        var lines = [
            "\(scope) .dt-scrollbar {", "  display: flex;", "  box-sizing: border-box;", "  block-size: \(thickness);",
            "  padding: \(px(metrics.inset));", "  gap: \(px(metrics.gap));", "}",
            "\(scope) .dt-scrollbar\(vertical) {", "  flex-direction: column;", "  block-size: auto;", "  inline-size: \(thickness);", "}",
            "\(scope) .dt-scrollbar__track {", "  flex: 1 1 0;", "  display: flex;", "  min-inline-size: 0;", "  min-block-size: 0;", "}",
            "\(scope) .dt-scrollbar\(vertical) .dt-scrollbar__track {", "  flex-direction: column;", "}",
            "\(scope) .dt-scrollbar__thumb {", "  flex: none;", "  display: flex;", "  align-items: center;", "  justify-content: center;",
            "  box-sizing: border-box;", "  block-size: 100%;", "}",
            "\(scope) .dt-scrollbar\(vertical) .dt-scrollbar__thumb {", "  block-size: auto;", "  inline-size: 100%;", "}",
            "\(scope) .dt-scrollbar__arrow {", "  flex: none;", "  box-sizing: border-box;", "  padding: 0;", "  border: 0;", "}",
        ]
        // a drawing that is a whole tile takes the tile's size, turned with the bar
        func size(_ role: SurfaceRole) -> (width: String, height: String, turned: (String, String))? {
            if case .pattern(let tile)? = surfaces.recipes[role]?[.rest]?.layers.last {
                return ("\(tile.width)px", "\(tile.height)px", ("\(tile.height)px", "\(tile.width)px"))
            }
            return nil
        }
        for (role, suffix) in [(SurfaceRole.scrollGrip, ".dt-scrollbar__grip"), (.scrollArrowStart, ".dt-scrollbar__arrow--start"),
                               (.scrollArrowEnd, ".dt-scrollbar__arrow--end")] {
            guard let box = size(role) else { continue }
            lines += ["\(scope) \(suffix) {", "  inline-size: \(box.width);", "  block-size: \(box.height);", "}",
                      "\(scope) .dt-scrollbar\(vertical) \(suffix) {", "  inline-size: \(box.turned.0);", "  block-size: \(box.turned.1);", "}"]
        }
        if surfaces.recipes[.scrollArrowStart] == nil {
            lines += ["\(scope) .dt-scrollbar__arrow {", "  inline-size: \(px(metrics.arrowLength));", "  block-size: 100%;", "}"]
        }
        if metrics.arrows == .together {
            lines += ["\(scope) .dt-scrollbar__track {", "  order: 1;", "}", "\(scope) .dt-scrollbar__arrow--start {", "  order: 2;", "}",
                      "\(scope) .dt-scrollbar__arrow--end {", "  order: 3;", "}"]
        }
        for (role, suffix) in parts {
            guard let recipe = surfaces.recipes[role]?[.rest] else { continue }
            for turned in [false, true] {
                let selector = turned ? "\(scope) .dt-scrollbar\(vertical)\(suffix == ".dt-scrollbar" ? "" : " " + suffix)" : "\(scope) \(suffix)"
                lines.append(selector + " {")
                lines.append(contentsOf: SurfaceCSS.declarations(for: turned ? recipe.transposed : recipe, resolve: reference, literal: literal)
                    .map { "  \($0);" })
                lines.append("}")
            }
        }
        // a part held down (before the inactive rules, which win when a bar has nothing to scroll): the thumb, its grip and the arrows
        let held: [(SurfaceRole, String)] = [(.scrollThumb, ".dt-scrollbar__thumb:active"), (.scrollGrip, ".dt-scrollbar__thumb:active .dt-scrollbar__grip"),
                                             (.scrollArrowStart, ".dt-scrollbar__arrow--start:active"), (.scrollArrowEnd, ".dt-scrollbar__arrow--end:active")]
        for (role, suffix) in held {
            guard let recipe = surfaces.recipes[role]?[.active] else { continue }
            for turned in [false, true] {
                lines.append((turned ? "\(scope) .dt-scrollbar\(vertical) \(suffix)" : "\(scope) \(suffix)") + " {")
                lines.append(contentsOf: SurfaceCSS.declarations(for: turned ? recipe.transposed : recipe, resolve: reference, literal: literal)
                    .map { "  \($0);" })
                lines.append("}")
            }
        }
        // an inactive bar (nothing to scroll): `aria-disabled="true"` on the bar redraws the parts that have a disabled recipe
        let inactive = "[aria-disabled=\"true\"]"
        for (role, suffix) in parts {
            guard let recipe = surfaces.recipes[role]?[.disabled] else { continue }
            let tail = suffix == ".dt-scrollbar" ? "" : " " + suffix
            for turned in [false, true] {
                let selector = turned ? "\(scope) .dt-scrollbar\(vertical)\(inactive)\(tail)" : "\(scope) .dt-scrollbar\(inactive)\(tail)"
                lines.append(selector + " {")
                lines.append(contentsOf: SurfaceCSS.declarations(for: turned ? recipe.transposed : recipe, resolve: reference, literal: literal)
                    .map { "  \($0);" })
                lines.append("}")
            }
        }
        return lines
    }

    /// The layout of a title bar: a row of `dt-titlebar__box--close|minimize|zoom` buttons, two `dt-titlebar__stripes` and a
    /// `dt-titlebar__title` in a `dt-titlebar`, in that markup order. The controls' `order` puts each on the side the theme's
    /// ``WindowControls`` names, so the markup does not change from one theme to another.
    private static func titleBarRules(_ theme: Theme, scope: String) -> [String] {
        guard let controls = theme.windowControls, let bar = controls.titleBar, theme.surfaces?.recipes[.titleBar] != nil else { return [] }
        func px(_ value: Double) -> String { SurfaceCSS.px(value) }
        var lines = [
            "\(scope) .dt-titlebar {",
            "  display: flex;",
            "  align-items: flex-start;",
            "  box-sizing: border-box;",
            "  block-size: \(px(bar.height));",
            "  padding: \(px(bar.inset.top)) \(px(bar.inset.trailing)) \(px(bar.inset.bottom)) \(px(bar.inset.leading));",
            "  gap: \(px(bar.gap));",
            "}",
            "\(scope) .dt-titlebar__box {",
            "  box-sizing: border-box;",
            "  flex: none;",
            "  inline-size: \(px(bar.boxSize));",
            "  block-size: \(px(bar.boxSize));",
            "  min-block-size: 0;",
            "  padding: 0;",
            "}",
            "\(scope) .dt-titlebar__stripes {",
            "  flex: 1 1 0;",
            "  block-size: \(px(bar.stripeHeight));",
            "}",
            "\(scope) .dt-titlebar__title {",
            "  flex: none;",
            "  align-self: center;",
            "  font-weight: 700;",
            "  line-height: 1;",
            "  white-space: nowrap;",
            "}",
        ]
        // a control whose drawing is a tile takes the tile's size, so a 14 px and a 15 px button each show whole
        let boxRoles: [(WindowControl, SurfaceRole)] = [(.close, .windowBox), (.zoom, .windowBoxZoom), (.minimize, .windowBoxMinimize)]
        for (control, role) in boxRoles {
            guard case .pattern(let tile)? = theme.surfaces?.recipes[role]?[.rest]?.layers.last,
                  tile.width != Int(exactly: bar.boxSize) || tile.height != Int(exactly: bar.boxSize) else { continue }
            lines += ["\(scope) .dt-titlebar__box--\(control.rawValue) {", "  inline-size: \(tile.width)px;", "  block-size: \(tile.height)px;", "}"]
        }
        // a control that follows another on its side is pulled to the controls' own spacing, which the bar's gap would otherwise set
        let pull = bar.boxGap - bar.gap
        func place(_ control: WindowControl, order: Int, follows: Bool) {
            lines += ["\(scope) .dt-titlebar__box--\(control.rawValue) {", "  order: \(order);"]
            if follows, pull != 0 { lines.append("  margin-inline-start: \(px(pull));") }
            lines.append("}")
        }
        for (index, control) in controls.leading.enumerated() { place(control, order: index - controls.leading.count, follows: index > 0) }
        for (index, control) in controls.trailing.enumerated() { place(control, order: index + 1, follows: index > 0) }
        return lines
    }

    // MARK: Colours

    private enum Selection {
        /// Every colour (the light block).
        case all
        /// Only a colour that has an increased-contrast value for the appearance.
        case increasedOnly
        /// Every colour, and the dark ramps that exist (the dark block).
        case darkOnly
    }

    private static func colourDeclarations(_ theme: Theme, appearance: Appearance, increased: Bool,
                                           only selection: Selection) -> [String] {
        func has(_ adaptive: Adaptive) -> Bool {
            guard selection == .increasedOnly else { return true }
            return (appearance == .dark ? adaptive.darkIncreased : adaptive.lightIncreased) != nil
        }
        func value(_ adaptive: Adaptive) -> ColorValue {
            adaptive.value(in: appearance, increasedContrast: increased)
        }
        var out: [String] = []
        let palette = theme.palette
        for role in ColorRole.allCases where has(palette[role]) {
            out.append(contentsOf: withRGB("--\(kebab(role.rawValue))", value(palette[role])))
        }
        for (index, entry) in palette.series.enumerated() where has(entry.color) {
            out.append("  --series-\(index + 1): \(value(entry.color).hex);")
        }
        for key in palette.extras.keys.sorted() {
            guard let adaptive = palette.extras[key], has(adaptive) else { continue }
            out.append(contentsOf: withRGB("--extra-\(kebab(key))", value(adaptive)))
        }
        guard selection != .increasedOnly else { return out }
        func ramp(_ name: String, _ ramp: Ramp) {
            let steps = appearance == .dark ? ramp.dark : ramp.light
            for (index, step) in (steps ?? []).enumerated() {
                out.append("  --\(name)-\(index + 1): \(step.hex);")
            }
        }
        ramp("sequential", palette.sequential)
        ramp("diverging", palette.diverging)
        for name in palette.extraRamps.keys.sorted() {
            if let extra = palette.extraRamps[name] { ramp("ramp-\(kebab(name))", extra) }
        }
        return out
    }

    private static func withRGB(_ name: String, _ color: ColorValue) -> [String] {
        ["  \(name): \(color.hex);", "  \(name)-rgb: \(color.rgb.red), \(color.rgb.green), \(color.rgb.blue);"]
    }

    // MARK: Structure

    private static func structureDeclarations(_ theme: Theme) -> [String] {
        let s = theme.structure
        var out: [String] = []
        func add(_ name: String, _ value: String) { out.append("  --\(name): \(value);") }
        func px(_ value: Double) -> String { "\(CSSNumber.string(value))px" }
        func number(_ value: Double) -> String { CSSNumber.string(value) }

        let rules = s.rules
        add("rule-title", px(rules.title.weight))
        add("rule-title-position", kebab(rules.title.position.rawValue))
        add("rule-title-color", "var(--\(kebab(rules.title.colour.rawValue)))")
        add("rule-title-inset", px(rules.title.inset))
        if let gap = rules.title.gapAfter { add("rule-title-gap-after", px(gap)) }
        add("rule-section", px(rules.section))
        add("rule-hairline", px(rules.hairline))
        add("rule-gridline", px(rules.gridline))
        add("rule-baseline", px(rules.baseline))
        add("rule-baseline-color", "var(--\(kebab(rules.baselineColour.rawValue)))")
        add("rule-page", px(rules.page))
        add("rule-reference", px(rules.reference.weight))
        add("rule-reference-dash", rules.reference.dash.isEmpty ? "none" : rules.reference.dash.map(number).joined(separator: " "))
        add("rule-plot-border", px(rules.plotBorder))
        add("rule-reference-color", "var(--\(kebab(rules.referenceColour.rawValue)))")
        add("rule-reference-label-color", "var(--\(kebab(rules.referenceLabelColour.rawValue)))")

        let layout = s.layout
        add("gutter", px(layout.gutter))
        add("space-unit", px(layout.baseUnit))
        add("columns", "\(layout.columns)")
        add("radius-container", px(layout.containerRadius))
        add("radius-control", px(layout.controlRadius))
        add("radius-annotation", px(layout.annotationRadius))
        add("margin-top", px(layout.margins.top))
        add("margin-leading", px(layout.margins.leading))
        add("margin-bottom", px(layout.margins.bottom))
        add("margin-trailing", px(layout.margins.trailing))
        add("gap-title", px(layout.gaps.title))
        add("gap-subtitle", px(layout.gaps.subtitle))
        add("gap-plot", px(layout.gaps.plot))
        add("gap-source", px(layout.gaps.source))
        add("gap-reference-label", px(layout.gaps.referenceLabel))
        if let controlHeight = layout.controlHeight {
            add("control-height", px(controlHeight))
            // Pads a label block-wise so a fixed-height control centres it: (height - line) / 2, never negative.
            let line = s.type.body.size * s.type.body.lineHeight
            add("control-pad-y", px(max(0, (controlHeight - line) / 2)))
        }
        add("card-border", px(layout.cardBorder))
        add("card-padding", px(layout.cardPadding))
        // The card chrome, and what a stylesheet needs from it. A custom property cannot branch, so the theme resolves the choice here
        // and components.css only reads the results. Ruled (Swiss): no surface, the section rule in ink across the top. Bordered: the
        // surface, no top rule (the border is --card-border, in the rule colour). The grid's column minimum is 88 base units (352 px at
        // 4 px), so three cards fit a 1200 px page with its padding, and one fits a phone.
        add("card-chrome", layout.cardChrome.rawValue)
        add("card-min", px(layout.baseUnit * Double(BrowserSupport.Breakpoints.cardMinimumWidthInBaseUnits)))
        add("card-gap", "var(--gutter)")
        switch layout.cardChrome {
        case .ruled:
            add("card-surface", "transparent")
            add("card-top-rule", "var(--rule-section)")
            add("card-top-color", "var(--ink)")
        case .bordered:
            add("card-surface", "var(--surface)")
            add("card-top-rule", "0px")
            add("card-top-color", "var(--rule)")
        }
        add("label-value-halo", px(s.labels.valueHalo))
        add("gridlines", kebab(layout.gridlines.rawValue))
        if let shadow = layout.shadow {
            add("shadow", "\(px(shadow.x)) \(px(shadow.y)) \(px(shadow.radius)) \(reference(shadow.colour))")
        } else {
            add("shadow", "none")
        }

        let marks = s.marks
        add("mark-line-width", px(marks.lineWidth))
        add("mark-point-size", px(marks.pointSize))
        add("mark-band-opacity", number(marks.bandOpacity))
        add("mark-selected-line-width", px(marks.selectedLineWidth))
        add("mark-area-opacity", number(marks.areaOpacity))
        add("mark-fill-opacity", number(marks.fillOpacity))
        add("mark-detail-line-width", px(marks.detailLineWidth))
        add("mark-bar-fill", kebab(marks.barFill.rawValue))
        add("mark-bar-width-ratio", number(marks.barWidthRatio))
        add("mark-bar-corner-radius", px(marks.barCornerRadius))
        add("mark-line-end", kebab(marks.lineEnd.rawValue))
        add("mark-default-fill", kebab(marks.defaultFill.rawValue))
        add("mark-default-emphasis", kebab(marks.defaultEmphasis.rawValue))
        add("mark-emphasis-fill", "var(--\(kebab(marks.emphasisFill.rawValue)))")
        if let tag = marks.tagMark {
            add("mark-tag-width", px(tag.width))
            add("mark-tag-height", px(tag.height))
            add("mark-tag-color", "var(--\(kebab(tag.colour.rawValue)))")
        }

        add("font-sans", FontStack.sans)
        add("font-mono", s.monospace.map { family($0.family) } ?? FontStack.mono)
        add("font-serif-new-york", FontStack.serifNewYork)
        add("font-serif-garamond", FontStack.serifGaramond)
        for role in TypeRole.allCases {
            let spec = s.type[role]
            let prefix = role.isUIRole ? "type-\(role == .uiTitle ? "title" : role.rawValue)" : "chart-\(kebab(role.rawValue))"
            add("\(prefix)-family", family(spec.family))
            // The display role at the package's display size is the fluid role, as in tokens.css.
            let fluid = role == .display && spec.size == TypeStyle.display.points ? TypeStyle.display.fluid : nil
            add("\(prefix)-size", fluid?.css ?? px(spec.size))
            add("\(prefix)-line", number(spec.lineHeight))
            add("\(prefix)-weight", "\(spec.weight)")
            add("\(prefix)-tracking", spec.tracking == 0 ? "0" : "\(number(spec.tracking))em")
            add("\(prefix)-transform", spec.uppercase ? "uppercase" : "none")
            add("\(prefix)-style", spec.italic ? "italic" : "normal")
        }
        if let mono = s.monospace {
            add("type-mono-size", px(mono.size))
            add("type-mono-line", number(mono.lineHeight))
            add("type-mono-weight", "\(mono.weight)")
        }
        return out
    }

    static func family(_ ref: FontFamilyRef) -> String {
        switch ref {
        case .sans: FontStack.sans
        case .mono: FontStack.mono
        case .serifNewYork: FontStack.serifNewYork
        case .serifGaramond: FontStack.serifGaramond
        case .named(let name, let fallback): "\"\(name)\", \(family(fallback))"
        }
    }

    /// A colour reference as a CSS value: the variable, or the variable at an opacity.
    private static func reference(_ ref: ColourReference) -> String {
        let name = ColorRole(rawValue: ref.source).map { "--\(kebab($0.rawValue))" } ?? "--extra-\(kebab(ref.source))"
        guard ref.opacity < 1 else { return "var(\(name))" }
        return "color-mix(in srgb, var(\(name)) \(CSSNumber.string((ref.opacity * 100).rounded()))%, transparent)"
    }

    /// `secondaryInk` to `secondary-ink`; an id or key that already has hyphens is left as it is.
    static func kebab(_ name: String) -> String {
        var out = ""
        for character in name {
            if character.isUppercase { out += "-" + character.lowercased() } else { out.append(character) }
        }
        return out
    }
}
